  sb_queue_event_data_struct_port_queues_struct_i_1_init((sb_queue_event_data_struct_port_queues_struct_i_1_t *) write_port_queue_1);

  sb_queue_event_data_struct_port_queues_struct_i_2_init((sb_queue_event_data_struct_port_queues_struct_i_2_t *) write_port_queue_2);

  sb_queue_event_data_struct_port_queues_struct_i_5_init((sb_queue_event_data_struct_port_queues_struct_i_5_t *) write_port_queue_5);

  producer_p_p_producer_initialize();
}

